package de.tum.cit.aet.sorting;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import static de.tum.in.test.api.util.ReflectionTestUtils.*;

class PolicyEdgeCaseTest {

    @Test
    void testPolicySelectsBubbleSortForEmptyList() throws ReflectiveOperationException {
        List<Date> emptyList = new ArrayList<>();
        Object context = newInstance("de.tum.cit.aet.sorting.Context");
        invokeMethod(context, getMethod(context, "setDates", List.class), emptyList);
        Object policy = newInstance("de.tum.cit.aet.sorting.Policy", context);
        invokeMethod(policy, getMethod(policy, "configure"));
        Object chosen = invokeMethod(context, getMethod(context, "getSortAlgorithm"));
        assertTrue(chosen instanceof BubbleSort, "Policy should select BubbleSort for empty list");
    }
}

