package de.tum.cit.aet.sorting;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;

class SortedOrderTest {

    private List<Date> randomDates(int size) {
        List<Date> list = new ArrayList<>();
        for (int i = 0; i < size; i++) {
            long randomMillis = ThreadLocalRandom.current().nextLong(0L, System.currentTimeMillis());
            list.add(new Date(randomMillis));
        }
        return list;
    }

    private boolean isSorted(List<Date> list) {
        for (int i = 0; i < list.size() - 1; i++) {
            if (list.get(i).compareTo(list.get(i + 1)) > 0) {
                return false;
            }
        }
        return true;
    }

    @Test
    void testBubbleSortSortedOrder() {
        List<Date> dates = randomDates(20);
        BubbleSort bubbleSort = new BubbleSort();
        bubbleSort.performSort(dates);
        assertTrue(isSorted(dates), "BubbleSort did not sort the list correctly");
    }

    @Test
    void testMergeSortSortedOrder() {
        List<Date> dates = randomDates(20);
        MergeSort mergeSort = new MergeSort();
        mergeSort.performSort(dates);
        assertTrue(isSorted(dates), "MergeSort did not sort the list correctly");
    }
}

